async function openShow(id,seasonNo){let s=SHOWS.find(x=>x.id===+id);if(!s)return;try{if(s.tmdbId&&(!s.seasonMeta||!s.seasonMeta.length)){s=fromTmdb(await tmdb(`/tv/${s.tmdbId}?language=es-ES`));storeShows([s])}}catch(e){showToast(e.message)}if(!s.tmdbId&&!s.seasonMeta){const totalSeasons=Math.max(1,Number(s.seasons)||1),totalEpisodes=Math.max(0,Number(s.episodes)||0);s={...s,seasonMeta:Array.from({length:totalSeasons},(_,i)=>({number:i+1,count:Math.floor(totalEpisodes/totalSeasons)+(i<totalEpisodes%totalSeasons?1:0)}))}}seasonNo=Number(seasonNo||s.seasonMeta?.[0]?.number||1);let episodes=[];if(s.tmdbId){try{episodes=(await tmdb(`/tv/${Number(s.tmdbId)}/season/${seasonNo}?language=es-ES`)).episodes||[]}catch(e){showToast(e.message)}}else{const count=s.seasonMeta?.find(x=>Number(x.number)===seasonNo)?.count||0;episodes=Array.from({length:count},(_,i)=>({episode_number:i+1,name:`Episodio ${i+1}`}))}if(!state.watchedEpisodes)state.watchedEpisodes={};const watched=state.watchedEpisodes[id]||[],inList=state.watchlist.includes(+id),backdrop=safeImage(s.backdrop);dialog.querySelector('#dialogContent').innerHTML=`<button class="dialog-close" data-action="close">✕</button><div class="dialog-hero" style="background-image:linear-gradient(0deg,#11111a 0%,transparent 80%),url('${backdrop}')"><div class="dialog-title"><p class="eyebrow">${esc(s.genre)} · ${esc(s.year)}</p><h2>${esc(s.title)}</h2><span>★ ${esc(s.rating)} · ${esc(s.status||`${Number(s.seasons)||0} temporadas`)}</span></div></div><div class="dialog-body"><p class="muted">${esc(s.desc)}</p><div class="actions"><button class="btn secondary" data-action="toggle-list" data-id="${Number(id)||0}">${inList?'− Quitar de mi lista':'＋ Mi lista'}</button></div><div class="actions">${(s.seasonMeta||[{number:1}]).map(x=>`<button class="btn ${Number(x.number)===seasonNo?'':'secondary'}" data-action="season" data-id="${Number(id)||0}" data-season="${Number(x.number)||0}">T${Number(x.number)||0}</button>`).join('')}</div><div class="episode-list">${episodes.map(ep=>{const number=Number(ep.episode_number)||0,key=`${seasonNo}-${number}`,seen=watched.includes(key);return `<div class="episode ${seen?'watched':''}"><span><strong>${number}. ${esc(ep.name||'Episodio')}</strong><br><small class="muted">${esc(ep.air_date||'Sin fecha')}${ep.runtime?` · ${Number(ep.runtime)||0} min`:''}</small></span><button data-action="episode-real" data-id="${Number(id)||0}" data-season="${seasonNo}" data-ep="${number}">${seen?'✓':'○'}</button></div>`}).join('')||'<div class="empty">No hay información de episodios.</div>'}</div></div>`;dialog.showModal()}
const loadShowContent=openShow;
openShow=async function(id,seasonNo){const firstOpen=!dialog.open;if(firstOpen){dialog.querySelector('#dialogContent').innerHTML='<div class="dialog-loading"><span class="spinner"></span><strong>Cargando episodios…</strong><small>La primera apertura puede tardar unos segundos.</small></div>';dialog.showModal()}dialog.setAttribute('aria-busy','true');const originalShowModal=dialog.showModal;dialog.showModal=()=>{};try{await loadShowContent(id,seasonNo)}finally{dialog.showModal=originalShowModal;dialog.removeAttribute('aria-busy')}};
function csvRows(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quote&&n==='"'){cell+='"';i++}else if(c==='"')quote=!quote;else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(Boolean))rows.push(row);if(rows.length<2)return[];const heads=rows.shift().map(x=>x.trim().toLowerCase());return rows.map(r=>Object.fromEntries(heads.map((h,i)=>[h,r[i]||''])))}
function collectRecords(value,out=[]){if(Array.isArray(value))value.forEach(x=>collectRecords(x,out));else if(value&&typeof value==='object'){out.push(value);Object.values(value).forEach(x=>{if(x&&typeof x==='object')collectRecords(x,out)})}return out}
function normaliseTvTime(objects){const found=new Map();for(const r of objects){const name=r.show_name||r.series_name||r.show_title||r.serie||r.show?.name||r.show?.title||r.series?.name||((r.type==='show'||r.type==='series')&&(r.name||r.title));if(!name||typeof name!=='string'||name.length>180)continue;const watchedFlag=r.watched??r.seen??r.is_watched??r.status;const hasEpisode=r.episode_number!=null||r.episode!=null||r.episode?.number!=null||r.season_number!=null;let item=found.get(name.toLowerCase())||{name:name.trim(),episodes:0,listed:true};if(hasEpisode&&(watchedFlag!==false&&watchedFlag!=='false'&&watchedFlag!=='unwatched'))item.episodes++;const explicit=Number(r.watched_episodes||r.seen_episodes||r.episodes_watched||0);item.episodes=Math.max(item.episodes,explicit);found.set(name.toLowerCase(),item)}return [...found.values()]}
async function parseTvTimeFiles(files){let objects=[];for(const file of files){const text=await file.text();try{objects.push(...collectRecords(JSON.parse(text)))}catch{objects.push(...csvRows(text))}}return normaliseTvTime(objects)}
async function resolveImport(records){const resolved=[];for(let i=0;i<records.length;i++){const rec=records[i];importDialog.querySelector('#importProgress').textContent=`Buscando ${i+1} de ${records.length}: ${rec.name}`;try{const data=await tmdb(`/search/tv?query=${encodeURIComponent(rec.name)}&language=es-ES`),hit=data.results[0];if(hit){let show=fromTmdb(hit);try{show=fromTmdb(await tmdb(`/tv/${hit.id}?language=es-ES`))}catch{}resolved.push({...rec,show})}else resolved.push({...rec,show:null})}catch(e){throw e}}return resolved}
async function startTvTimeImport(files){if(!files.length)return;if(!tmdbToken){showToast('Configura primero el token de TMDB');return}importDialog.querySelector('#importContent').innerHTML=`<div class="import-summary"><p class="eyebrow">Importando TV Time</p><h2>Analizando tus archivos</h2><p class="muted" id="importProgress"><span class="spinner"></span> Leyendo datos…</p></div>`;importDialog.showModal();try{const records=await parseTvTimeFiles(files);if(!records.length)throw new Error('No encontramos nombres de series en esos archivos');const resolved=await resolveImport(records),ok=resolved.filter(x=>x.show);importDialog.querySelector('#importContent').innerHTML=`<div class="import-summary"><p class="eyebrow">Revisión</p><h2>${ok.length} de ${records.length} series identificadas</h2><p class="muted">Comprueba el resultado. Las series no encontradas no se importarán.</p><div class="import-results">${resolved.map(x=>`<div class="import-item ${x.show?'':'missing'}"><span><b>${esc(x.name)}</b><br><small>${Number(x.episodes)||0} episodios detectados</small></span><span>${x.show?`✓ ${esc(x.show.title)}`:'No encontrada'}</span></div>`).join('')}</div><div class="actions"><button class="btn" data-action="confirm-tvtime">Importar ${ok.length} series</button><button class="btn secondary" data-action="cancel-import">Cancelar</button></div></div>`;importDialog._resolved=resolved}catch(e){importDialog.querySelector('#importContent').innerHTML=`<div class="import-summary"><h2>No se pudo preparar la importación</h2><p class="muted">${esc(e.message)}</p><button class="btn secondary" data-action="cancel-import">Cerrar</button></div>`}}
function confirmTvTimeImport(){const items=(importDialog._resolved||[]).filter(x=>x.show);storeShows(items.map(x=>x.show));items.forEach(x=>{const id=x.show.id;if(x.episodes>0)state.watching[id]=Math.max(state.watching[id]||0,x.episodes);else if(!state.watchlist.includes(id))state.watchlist.push(id)});save();persistServer().catch(()=>{});importDialog.close();render('profile');showToast(`${items.length} series importadas`)}
document.addEventListener('click',async event=>{const action=event.target.closest('[data-action]')?.dataset.action;if(action!=='logout')return;event.preventDefault();event.stopImmediatePropagation();try{await flushSave()}catch{}await apiFetch('./api.php?action=logout',{method:'POST'});localStorage.removeItem(backupKey());localStorage.removeItem('maraton-state');localStorage.removeItem('maraton-tmdb-token');localStorage.removeItem('maraton-catalog');location.reload()},true);
