function updateEpisodeUI(id,season){const watched=state.watchedEpisodes[id]||[],changedEpisodes=new Map();document.querySelectorAll(`[data-action="episode-real"][data-id="${Number(id)}"][data-season="${Number(season)}"]`).forEach(button=>{const row=button.closest('.episode'),seen=watched.includes(`${season}-${button.dataset.ep}`),wasSeen=row?row.classList.contains('watched'):button.dataset.seen==='true';button.dataset.seen=String(seen);if(row)button.textContent=seen?'✓':'○';row?.classList.toggle('watched',seen);if(wasSeen!==seen)changedEpisodes.set(String(button.dataset.ep),seen)});changedEpisodes.forEach((seen,episode)=>persistEpisodeRow(id,season,episode,seen).catch(error=>showToast(error.message)));if(changedEpisodes.size&&currentView==='calendar')setTimeout(()=>render('calendar'),0)}
function addHistory(id,keys){const show=SHOWS.find(item=>item.id==id);if(!show||!keys.length)return;const now=new Date().toISOString(),entries=keys.map(value=>{const [season,episode]=value.split('-');return{showId:Number(id),title:String(show.title),episode:`T${season} · E${episode}`,at:now}}),labels=new Set(entries.map(item=>item.episode));state.history=[...entries,...state.history.filter(item=>!(item.showId==id&&labels.has(item.episode)))].slice(0,200)}
function showPreviousPrompt(id,season,missing){dialog.querySelector('.episode-prompt')?.remove();const prompt=document.createElement('div');prompt.className='episode-prompt';prompt.innerHTML=`<div><strong>¿Marcar también los anteriores?</strong><p>Faltan ${missing.length} ${missing.length===1?'episodio':'episodios'} de esta temporada.</p></div><div><button class="btn" data-action="confirm-previous">Marcar anteriores</button><button class="btn secondary" data-action="cancel-previous">Solo este</button></div>`;dialog.querySelector('.episode-list')?.before(prompt);pendingPrevious={id:String(id),season:Number(season),missing};prompt.scrollIntoView({block:'nearest'})}
document.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action;if(!['episode-real','confirm-previous','cancel-previous'].includes(action))return;event.preventDefault();event.stopImmediatePropagation();if(action==='cancel-previous'){pendingPrevious=null;dialog.querySelector('.episode-prompt')?.remove();return}if(action==='confirm-previous'){if(!pendingPrevious)return;const{id,season,missing}=pendingPrevious,list=state.watchedEpisodes[id]||[];missing.forEach(key=>{if(!list.includes(key))list.push(key)});state.watchedEpisodes[id]=list;state.watching[id]=list.length;addHistory(id,missing);pendingPrevious=null;dialog.querySelector('.episode-prompt')?.remove();updateEpisodeUI(id,season);save();showToast('Episodios anteriores marcados');return}const button=event.target.closest('[data-action="episode-real"]'),id=button.dataset.id,season=Number(button.dataset.season),episode=Number(button.dataset.ep),key=`${season}-${episode}`,list=state.watchedEpisodes[id]||[],index=list.indexOf(key);if(index>=0){list.splice(index,1);state.history=state.history.filter(item=>!(item.showId==id&&item.episode===`T${season} · E${episode}`));dialog.querySelector('.episode-prompt')?.remove();pendingPrevious=null;showToast('Episodio desmarcado')}else{list.push(key);addHistory(id,[key]);const missing=Array.from({length:Math.max(0,episode-1)},(_,i)=>`${season}-${i+1}`).filter(previous=>!list.includes(previous));if(missing.length)showPreviousPrompt(id,season,missing);showToast('Episodio visto')}state.watchedEpisodes[id]=list;state.watching[id]=list.length;state.showStatus[id]=state.showStatus[id]||'watching';updateEpisodeUI(id,season);save()},true);
document.addEventListener('click',async e=>{const v=e.target.closest('[data-view]')?.dataset.view,show=e.target.closest('[data-show]')?.dataset.show,a=e.target.closest('[data-action]'),id=a?.dataset.id;if(v)render(v);if(show)openShow(show);if(!a)return;if(a.dataset.action==='close')dialog.close();if(a.dataset.action==='toggle-list'){const n=+id,i=state.watchlist.indexOf(n);i>=0?state.watchlist.splice(i,1):state.watchlist.push(n);save();showToast(i>=0?'Eliminada de tu lista':'Añadida a tu lista');if(dialog.open)openShow(n);else render();}if(a.dataset.action==='watch-next'){state.watching[id]=Math.min((state.watching[id]||0)+1,SHOWS.find(s=>s.id==id).episodes);save();showToast('Progreso actualizado');openShow(id);}if(a.dataset.action==='episode'){state.watching[id]=+a.dataset.ep;save();showToast('Episodio marcado');openShow(id);}if(a.dataset.action==='export'){const backup={version:3,exportedAt:new Date().toISOString(),state,catalog:SHOWS.filter(s=>s.tmdbId)};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='maraton-copia.json';link.click();URL.revokeObjectURL(url);}if(a.dataset.action==='save-token'){const input=document.querySelector('#tmdbToken');tmdbToken=input.value.trim();tmdbCache.clear();save();a.innerHTML='<span class="spinner"></span>';try{await tmdb('/configuration');showToast('TMDB conectado correctamente');render('profile')}catch(err){showToast(err.message);a.textContent='Guardar y probar'}}if(a.dataset.action==='import-tvtime')document.querySelector('#tvtimeFiles').click();if(a.dataset.action==='confirm-tvtime')confirmTvTimeImport();if(a.dataset.action==='cancel-import')importDialog.close();if(a.dataset.action==='logout'){try{await saveInFlight}catch{}await apiFetch('./api.php?action=logout',{method:'POST'});localStorage.removeItem(backupKey());localStorage.removeItem('maraton-state');localStorage.removeItem('maraton-tmdb-token');localStorage.removeItem('maraton-catalog');location.reload()}});
