document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;if(a.dataset.action==='season')openShow(a.dataset.id,+a.dataset.season);if(a.dataset.action==='episode-real'){const id=a.dataset.id,season=Number(a.dataset.season),episode=Number(a.dataset.ep),key=`${season}-${episode}`;state.watchedEpisodes=state.watchedEpisodes||{};const list=state.watchedEpisodes[id]||[],index=list.indexOf(key),show=SHOWS.find(item=>item.id==id),newlyMarked=[];if(index>=0){list.splice(index,1);state.history=state.history.filter(item=>!(item.showId==id&&item.episode===`T${season} · E${episode}`));showToast('Episodio desmarcado')}else{const missing=Array.from({length:Math.max(0,episode-1)},(_,i)=>`${season}-${i+1}`).filter(previous=>!list.includes(previous)),markPrevious=missing.length>0&&window.confirm(`No has marcado ${missing.length===1?'el episodio anterior':`los ${missing.length} episodios anteriores`} de esta temporada. ¿Quieres marcarlos también?`);if(markPrevious){missing.forEach(previous=>{list.push(previous);newlyMarked.push(previous)})}list.push(key);newlyMarked.push(key);showToast(markPrevious?'Episodios anteriores marcados':'Episodio visto')}state.watchedEpisodes[id]=[...new Set(list)];state.watching[id]=state.watchedEpisodes[id].length;state.showStatus[id]=state.showStatus[id]||'watching';if(show&&newlyMarked.length){const now=new Date().toISOString(),entries=newlyMarked.map(value=>{const [s,e]=value.split('-');return{showId:Number(id),title:String(show.title),episode:`T${s} · E${e}`,at:now}});const markedLabels=new Set(entries.map(item=>item.episode));state.history=[...entries,...state.history.filter(item=>!(item.showId==id&&markedLabels.has(item.episode)))].slice(0,200)}dialog.querySelectorAll(`[data-action="episode-real"][data-id="${Number(id)}"][data-season="${season}"]`).forEach(button=>{const seen=state.watchedEpisodes[id].includes(`${season}-${button.dataset.ep}`);button.textContent=seen?'✓':'○';button.closest('.episode')?.classList.toggle('watched',seen)});save()}});
