window.addEventListener('pagehide',()=>{if(serverSavePending||saveRevision>lastSavedRevision)apiFetch('./api.php?action=data',{method:'POST',keepalive:true,headers:{'Content-Type':'application/json'},body:JSON.stringify(serverSnapshot())}).catch(()=>{})});
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
new MutationObserver(()=>{const body=dialog.querySelector('.dialog-body'),anchor=body?.querySelector('[data-action="toggle-list"]'),existing=body?.querySelector('.tracking-panel');if(!body||!anchor||existing)return;const id=Number(anchor.dataset.id)||0,panel=document.createElement('div');panel.className='tracking-panel';panel.innerHTML=`<label>Estado<select data-action="show-status" data-id="${id}"><option value="watching">Viendo</option><option value="paused">En pausa</option><option value="completed">Terminada</option><option value="dropped">Abandonada</option></select></label><label>Mi valoración<select data-action="rate-show" data-id="${id}"><option value="">Sin valorar</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}">${i+1}/10</option>`).join('')}</select></label>`;panel.querySelector('[data-action="show-status"]').value=state.showStatus[id]||'watching';panel.querySelector('[data-action="rate-show"]').value=state.ratings[id]||'';anchor.closest('.actions').before(panel)},).observe(dialog.querySelector('#dialogContent'),{childList:true});
document.addEventListener('change',e=>{const action=e.target.dataset.action,id=Number(e.target.dataset.id)||0;if(action==='show-status'){state.showStatus[id]=['watching','paused','completed','dropped'].includes(e.target.value)?e.target.value:'watching';if(!state.watching[id])state.watching[id]=0;save();persistTrackRow(id).catch(error=>showToast(error.message));showToast('Estado actualizado')}if(action==='rate-show'){const rating=Number(e.target.value);if(rating>=1&&rating<=10)state.ratings[id]=rating;else delete state.ratings[id];save();persistTrackRow(id).catch(error=>showToast(error.message));showToast(rating?'Valoración guardada':'Valoración eliminada')}});
document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action==='toggle-profile-edit'){const form=document.querySelector('#profileForm');if(form)form.hidden=!form.hidden}});
document.addEventListener('submit',async e=>{if(e.target.id!=='profileForm')return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target)),name=String(data.name||'').trim(),bio=String(data.bio||'').trim(),color=String(data.avatarColor||'');if(name.length<2||name.length>80){showToast('El nombre debe tener entre 2 y 80 caracteres');return}state.name=name;state.profile={bio:bio.slice(0,240),avatarColor:/^#[0-9a-f]{6}$/i.test(color)?color:'#ff2d74'};save();try{await persistProfile();render('profile');showToast('Perfil guardado')}catch(error){showToast(error.message)}});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js');
function setAuthMode(mode,hasUsers=true){authMode=mode;const register=mode==='register',password=document.querySelector('[name=password]'),name=document.querySelector('[name=name]'),confirm=document.querySelector('[name=confirmPassword]');document.querySelector('#authTitle').textContent=register?'Crear tu cuenta':'Iniciar sesión';document.querySelector('#authHelp').textContent=register?'Empieza a construir tu biblioteca personal.':'Introduce tu usuario y contraseña para entrar.';document.querySelector('#nameField').hidden=!register;document.querySelector('#confirmField').hidden=!register;document.querySelector('#registerPrivacy').hidden=!register;document.querySelector('#passwordStrength').hidden=!register;document.querySelector('#authSubmit').textContent=register?'Crear mi cuenta':'Entrar';password.autocomplete=register?'new-password':'current-password';name.required=register;confirm.required=register;if(!register){name.value='';confirm.value=''}document.querySelectorAll('[data-auth-mode]').forEach(button=>{const active=button.dataset.authMode===mode;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});document.querySelector('#authError').textContent='';if(!hasUsers&&mode==='login')document.querySelector('#authHelp').textContent='Todavía no hay cuentas. Selecciona “Crear cuenta” para comenzar.'}
document.querySelectorAll('[data-auth-mode]').forEach(button=>button.addEventListener('click',()=>setAuthMode(button.dataset.authMode)));
document.querySelector('[data-action="toggle-password"]').addEventListener('click',e=>{const input=document.querySelector('[name=password]'),show=input.type==='password';input.type=show?'text':'password';e.currentTarget.textContent=show?'Ocultar':'Ver';e.currentTarget.setAttribute('aria-label',show?'Ocultar contraseña':'Mostrar contraseña')});
document.querySelector('[name=password]').addEventListener('input',e=>{const value=e.target.value,score=[value.length>=8,value.length>=12,/[a-z]/.test(value)&&/[A-Z]/.test(value),/\d/.test(value),/[^\w]/.test(value)].filter(Boolean).length,bar=document.querySelector('#passwordStrength i'),label=document.querySelector('#passwordStrength small'),levels=['Usa 8 caracteres o más','Contraseña débil','Contraseña aceptable','Contraseña buena','Contraseña fuerte','Contraseña muy fuerte'];bar.style.width=`${score*20}%`;bar.style.background=score<2?'#ff6b6b':score<4?'#ffb74d':'#35d69f';label.textContent=levels[score]});
authForm.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(authForm)),error=document.querySelector('#authError'),button=document.querySelector('#authSubmit');error.textContent='';if(!authForm.checkValidity()){authForm.reportValidity();return}if(authMode==='register'&&b.password!==b.confirmPassword){error.textContent='Las contraseñas no coinciden';document.querySelector('[name=confirmPassword]').focus();return}delete b.confirmPassword;button.disabled=true;const original=button.textContent;button.innerHTML='<span class="spinner"></span> Comprobando…';try{const r=await apiFetch(`./api.php?action=${authMode}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),data=await r.json();if(!r.ok)throw new Error(data.error||'No se pudo acceder');currentUser=data.user;csrfToken=data.csrfToken||csrfToken;if(authMode==='register'){state={...structuredClone(defaultState),name:data.user.name};await apiFetch('./api.php?action=data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(serverSnapshot())})}authScreen.hidden=true;authForm.reset();await loadUserData()}catch(err){error.textContent=err.message}finally{button.disabled=false;button.textContent=original}});
async function loadUserData(){try{const response=await fetch('./api.php?action=data',{cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error(data.error||'No se pudieron cargar los datos');const local=readLocalBackup(),recoverLocal=data.exists&&activityScore(data.state)===0&&activityScore(local?.state)>0;if(recoverLocal){state=ensureState(local.state);tmdbToken=data.tmdbToken||'';SHOWS=[];if(Array.isArray(local.catalog))storeShows(local.catalog);await persistServer();showToast('Datos recuperados y migrados a SQLite')}else if(data.exists&&data.state){state=ensureState(data.state);tmdbToken=data.tmdbToken||'';SHOWS=[];if(Array.isArray(data.catalog))storeShows(data.catalog);writeLocalBackup(Date.parse(data.savedAt)||Date.now())}else{state=ensureState({...structuredClone(defaultState),name:currentUser.name});writeLocalBackup();await persistServer()}render()}catch(error){const local=readLocalBackup();if(local?.state){state=ensureState(local.state);SHOWS=[];if(Array.isArray(local.catalog))storeShows(local.catalog);render();showToast('Sin conexión: usando copia de emergencia')}else throw error}}
async function bootstrap(){try{localStorage.removeItem('maraton-state');localStorage.removeItem('maraton-tmdb-token');localStorage.removeItem('maraton-catalog');const r=await fetch('./api.php?action=status',{cache:'no-store'}),status=await r.json();csrfToken=status.csrfToken||'';if(!status.authenticated){setAuthMode(status.hasUsers?'login':'register',status.hasUsers);authScreen.hidden=false;return}currentUser=status.user;authScreen.hidden=true;await loadUserData()}catch{authScreen.hidden=false;document.querySelector('#authError').textContent='No se pudo conectar con el servidor local.'}}
bootstrap();
